#requires -Version 5.1
param([ValidateSet('install','remove')][string]$Action,[Parameter(Mandatory=$true)][string]$Root,[Parameter(Mandatory=$true)][string]$Data)
$ErrorActionPreference='Stop'
# Lertaro background service integration. The application registers
# LertaroService from whichever version directory it happens to run in, so a
# payload Piko later replaces leaves the registration pointing at a directory
# that no longer exists and every start fails with "system cannot find the
# file". This anchors the registration at the package's stable current
# junction, which follows the selected version, and journals what it wrote so
# removal deletes exactly that service.
$Root=[IO.Path]::GetFullPath($Root).TrimEnd('\')
$apps=Split-Path -Parent $Root
$stable=Join-Path $apps 'current'
$image=Join-Path $stable 'Lertaro.Service.exe'
$journal=Join-Path $Data 'piko-lertaro-service.json'
$serviceName='LertaroService'
$displayName='Lertaro Background Service'
function Get-ImagePath([string]$PathName){
 $p=$PathName.Trim()
 if($p.StartsWith('"')){
  $end=$p.IndexOf('"',1)
  if($end -gt 1){$p=$p.Substring(1,$end-1)}else{$p=$p.Substring(1)}
 }else{
  $space=$p.IndexOf(' ')
  if($space -gt 0){$p=$p.Substring(0,$space)}
 }
 $p
}
function Test-Under([string]$PathName,[string]$Parent){
 if(!$PathName){return $false}
 (Get-ImagePath $PathName).StartsWith($Parent.TrimEnd('\')+'\',[System.StringComparison]::OrdinalIgnoreCase)
}
function Get-Registration{Get-CimInstance Win32_Service -Filter ("Name='"+$serviceName+"'")}
function Invoke-Sc([string[]]$Arguments){
 $out=& sc.exe @Arguments 2>&1
 $code=$LASTEXITCODE
 if($code -ne 0){throw ('sc.exe '+($Arguments -join ' ')+' failed with exit code '+$code+': '+(($out|Out-String).Trim()))}
 ($out|Out-String).Trim()
}
function Stop-Registration{
 $registration=Get-Registration
 if(!$registration){return}
 if($registration.State -ne 'Stopped'){
  $null=Invoke-Sc @('stop',$serviceName)
  $deadline=(Get-Date).AddSeconds(60)
  while((Get-Date) -lt $deadline){
   Start-Sleep -Milliseconds 500
   $current=Get-Registration
   if(!$current -or $current.State -eq 'Stopped'){break}
  }
  $current=Get-Registration
  if($current -and $current.State -ne 'Stopped'){throw ('LertaroService did not stop (state '+$current.State+')')}
 }
 if($current -and $current.ProcessId){Stop-Process -Id $current.ProcessId -Force -ErrorAction SilentlyContinue}
}
if(!(Test-Path -LiteralPath $stable -PathType Container)){throw 'The package current junction is missing: '+$stable}
if(!(Test-Path -LiteralPath $image -PathType Leaf)){throw 'The selected version does not ship Lertaro.Service.exe: '+$image}
$registration=Get-Registration
if($registration -and !(Test-Under $registration.PathName $apps)){
 throw ('An existing Lertaro service points outside this package ('+$registration.PathName+'); remove it through its owner first')
}
if($Action -eq 'install'){
 $null=[IO.Directory]::CreateDirectory($Data)
 $record=$null
 if(Test-Path -LiteralPath $journal -PathType Leaf){
  $record=Get-Content -LiteralPath $journal -Raw|ConvertFrom-Json
  if($record.schemaVersion -ne 1){throw 'Unsupported service ownership receipt'}
  if($record.stable -ine $stable){throw 'The service journal belongs to a different package directory'}
 }
 if($registration){
  # The application's own registration cannot follow a replaced version, so
  # rebuild it from the junction rather than editing a stale path in place.
  Stop-Registration
  $null=Invoke-Sc @('delete',$serviceName)
  $deadline=(Get-Date).AddSeconds(30)
  while((Get-Registration) -and (Get-Date) -lt $deadline){Start-Sleep -Milliseconds 500}
  if(Get-Registration){throw 'Failed to replace the existing Lertaro service registration'}
 }
 # New-Service hands the image path to CreateService verbatim, so the quotes a
 # path containing spaces needs survive; sc.exe would re-parse them away.
 # Delayed auto start is applied afterwards because New-Service only accepts
 # that startup mode on PowerShell 7, and 5.1 remains the fallback host.
 $quoted=[string]::Format('{0}{1}{0} --service',[char]34,$image)
 $null=New-Service -Name $serviceName -BinaryPathName $quoted -DisplayName $displayName -StartupType Automatic
 $null=Invoke-Sc @('config',$serviceName,'start=','delayed-auto')
 $null=Invoke-Sc @('failure',$serviceName,'reset=','86400','actions=','restart/15000/restart/30000/restart/60000')
 $null=Invoke-Sc @('start',$serviceName)
 $deadline=(Get-Date).AddSeconds(60)
 $ok=$false
 do{
  Start-Sleep -Milliseconds 500
  $current=Get-Registration
  if($current -and $current.State -eq 'Running' -and ((Get-ImagePath $current.PathName) -ieq $image)){$ok=$true;break}
 }while((Get-Date) -lt $deadline)
 if(!$ok){
  $state=if($current){$current.State}else{'absent'}
  throw ('LertaroService did not reach Running at '+$image+' (state '+$state+')')
 }
 @{schemaVersion=1;stable=$stable;image=$image;service=$serviceName;state='installed';installed=(Get-Date).ToUniversalTime().ToString('o')}|ConvertTo-Json|Set-Content -LiteralPath $journal -Encoding UTF8
 Write-Output ('Installed Lertaro service registration at '+$image)
}else{
 if(!(Test-Path -LiteralPath $journal -PathType Leaf)){throw 'No owned Lertaro service registration to remove'}
 $record=Get-Content -LiteralPath $journal -Raw|ConvertFrom-Json
 if($record.schemaVersion -ne 1){throw 'Unsupported service ownership receipt'}
 if($record.stable -ine $stable){throw 'The service journal belongs to a different package directory'}
 if(!$registration){
  Remove-Item -LiteralPath $journal -Force
  Write-Output 'Lertaro service was already absent'
  return
 }
 Stop-Registration
 $null=Invoke-Sc @('delete',$serviceName)
 $deadline=(Get-Date).AddSeconds(30)
 while((Get-Registration) -and (Get-Date) -lt $deadline){Start-Sleep -Milliseconds 500}
 if(Get-Registration){throw 'Failed to delete the Lertaro service registration'}
 Remove-Item -LiteralPath $journal -Force
 Write-Output 'Removed Lertaro service registration'
}
